values (
  'homepage.creative-services',
  '{"eyebrow":"What I can help with","titleMain":"CREATIVE","titleAccent":"SERVICES","services":[{"key":"brand","number":"01","cardTitle":"Brand Identity","cardDescription":"Logo systems, visual direction and consistent brand assets.","modalEyebrow":"Service workflow","modalTitle":"Brand Identity","modalSummary":"I build a practical visual identity system that can stay consistent across social media, print and everyday brand use.","workflow":["Discovery and brief: understand the business, audience, goals, personality and where the identity will be used.","Research and direction: review competitors, references and visual opportunities before choosing a clear creative direction.","Concept development: create logo and identity concepts with typography, color and supporting visual elements.","Refinement: improve the selected direction through feedback, spacing, balance, color and real-use testing.","Brand system rollout: prepare the main logo, alternate marks and practical brand assets for common use cases.","Final handoff: organize master files, exports and a clear usage reference so the identity is easy to use consistently."],"deliverables":["Primary and alternate logo files","Color and typography system","Brand marks / supporting assets","Social/profile assets as scoped","Basic brand usage reference"],"tools":["Adobe Illustrator","Adobe Photoshop","Mockups and presentation boards"],"needs":["Business/brand name and goals","Target audience","Competitors or references","Required applications","Deadline and key constraints"],"handoff":"Organized source and export files such as AI, SVG, PDF, PNG and JPG, plus color/font references based on the agreed scope."},{"key":"social","number":"02","cardTitle":"Social & Marketing Design","cardDescription":"Campaign posts, ads and promotional social media visuals.","modalEyebrow":"Service workflow","modalTitle":"Social & Marketing Design","modalSummary":"I turn a campaign, offer or content idea into a consistent set of platform-ready promotional visuals.","workflow":["Campaign brief: define the goal, offer, audience, platform and required formats.","Content and asset check: collect copy, product photos, logos, brand rules and any required call-to-action.","Visual direction: establish hierarchy, layout, typography and a repeatable campaign look.","Design production: create the main design first, then build required post, story, ad or banner variations.","Review and revisions: refine messaging, visual balance and consistency based on feedback.","Export and delivery: prepare correctly sized files for each platform and organize the final campaign set."],"deliverables":["Social media posts","Story / vertical formats","Ad and campaign visuals","Promotional banners","Editable template files when scoped"],"tools":["Adobe Photoshop","Adobe Illustrator","Platform size and export standards"],"needs":["Final or draft copy","Brand/logo assets","Product or campaign images","Target platform and sizes","Offer, CTA and deadline"],"handoff":"Platform-ready JPG/PNG files, plus editable source files when included in the project scope."},{"key":"sports","number":"03","cardTitle":"Sports & Jersey Design","cardDescription":"Team identity, match graphics and apparel concepts.","modalEyebrow":"Service workflow","modalTitle":"Sports & Jersey Design","modalSummary":"I create team-focused visual systems that connect identity, jerseys and tournament or match-day graphics.","workflow":["Team brief: collect team identity, colors, tournament context, sponsors and practical requirements.","Visual direction: define a strong sports look that works across kit, social graphics and event communication.","Jersey or graphic concepts: develop front/back layouts, typography, numbers, sponsor placement and supporting visuals.","Mockup and review: show the design in realistic context and refine details with the team.","Production preparation: clean dimensions, placements and export formats for printing or digital use.","Final rollout: deliver the approved assets and any supporting match, tournament or team graphics included in scope."],"deliverables":["Jersey concepts and mockups","Team identity graphics","Match / tournament visuals","Sponsor and number placement","Print-ready artwork when required"],"tools":["Adobe Illustrator","Adobe Photoshop","Sportswear mockups and print templates"],"needs":["Team logo and colors","Sponsor logos","Player/number requirements","Printer/manufacturer template if available","Tournament or campaign needs"],"handoff":"Approved digital artwork and production-ready files based on the printer or manufacturer requirements provided."},{"key":"video","number":"04","cardTitle":"Video & Motion Content","cardDescription":"Short-form edits, reels and promotional motion content.","modalEyebrow":"Service workflow","modalTitle":"Video & Motion Content","modalSummary":"I edit short-form promotional content with clear pacing, brand consistency and platform-focused delivery.","workflow":["Brief and format: confirm objective, platform, duration, style and final aspect ratio.","Asset review: organize footage, images, logo, script, captions and other supplied material.","Rough cut: build the core sequence, pacing and story structure before detailed polish.","Motion and brand layer: add titles, transitions, graphic elements and brand styling where needed.","Review and refinement: adjust timing, text, sequence and visual details from feedback.","Final export: deliver optimized versions for the requested social or digital platforms."],"deliverables":["Reels / short-form edits","Promotional videos","Branded text and motion graphics","Platform-specific versions","Thumbnail or cover support when scoped"],"tools":["Adobe Premiere Pro","CapCut","Photoshop / Illustrator for supporting graphics"],"needs":["Footage and source assets","Target platform","Desired duration","Script/copy if available","Brand assets and deadline"],"handoff":"Final MP4 exports in the agreed sizes and resolutions, with project/source files included only when part of the agreed scope."},{"key":"marketing","number":"05","cardTitle":"Digital Marketing Support","cardDescription":"Campaign support, social sales flow and customer handling.","modalEyebrow":"Service workflow","modalTitle":"Digital Marketing Support","modalSummary":"I connect campaign visuals with a practical content and customer-response flow so marketing is easier to run consistently.","workflow":["Goal and offer review: define what the campaign needs to achieve and what action the audience should take.","Audience and channel planning: choose the platform, message angle and content types that fit the campaign.","Creative plan: map the required posts, ads, offers and supporting visuals.","Campaign support: prepare content assets and help structure the launch or boosting workflow as scoped.","Customer response flow: organize common replies, confirmation messages and follow-up steps where useful.","Review and improve: look at available campaign results and identify practical changes for the next round."],"deliverables":["Campaign creative plan","Social content and ad variations","Offer / CTA structure","Customer response templates","Basic campaign review support"],"tools":["Design tools","Social platform publishing / campaign tools as available","Simple tracking and reporting sheets"],"needs":["Business goal and offer","Target customer","Budget or campaign limits when relevant","Existing page/account assets","Available performance data"],"handoff":"A clear set of campaign assets, content directions and operating notes based on the agreed level of marketing support."},{"key":"workflow","number":"06","cardTitle":"Business Workflow Design","cardDescription":"Clear digital flows for inventory, orders and reporting.","modalEyebrow":"Service workflow","modalTitle":"Business Workflow Design","modalSummary":"I map repeated business tasks into a clearer digital workflow so products, orders, delivery and reporting are easier to manage.","workflow":["Process discovery: understand how the business currently handles products, customers, orders, payments and reporting.","Workflow mapping: define the stages, responsibilities, statuses and information that need to move between them.","Module and data design: structure areas such as sourcing, inventory, pricing, sales, courier, expenses and reports.","Interface / system planning: turn the workflow into practical screens, forms, tables and actions.","Testing with real scenarios: check the flow using realistic orders, stock changes and business exceptions.","Refinement and handoff: simplify confusing steps, document the final flow and prepare the agreed implementation or prototype."],"deliverables":["Process and module map","Data / status structure","Forms, tables and dashboard flow","Operational templates","Prototype or implementation scope as agreed"],"tools":["Workflow mapping","Spreadsheets / structured data","Web and database tools as required by the project"],"needs":["Current business process","Existing records or sample data","Roles and responsibilities","Problems to solve first","Required reports and outputs"],"handoff":"A documented operating flow with the agreed templates, prototype or system structure, organized so future features can be added without rebuilding the process from zero."}]}'::jsonb,
